package com.kampotourism.itinerary;
import com.kampotourism.common.PageResponse; import com.kampotourism.content.ContentStatus; import com.kampotourism.itinerary.ItineraryDtos.*; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import jakarta.validation.Valid; import java.net.URI; import java.util.List; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/itineraries") @SecurityRequirement(name="bearer") public class AdminItineraryController {private final ItineraryService service;public AdminItineraryController(ItineraryService service){this.service=service;}@GetMapping public PageResponse<AdminDetail> list(@RequestParam(defaultValue="all")String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return service.adminList(status,page,size);}@PostMapping public ResponseEntity<AdminDetail> create(@Valid @RequestBody CreateRequest r){AdminDetail x=service.create(r);return ResponseEntity.created(URI.create("/api/v1/admin/itineraries/"+x.id())).body(x);}@GetMapping("/{id}")public AdminDetail get(@PathVariable long id){return service.adminGet(id);}@PutMapping("/{id}")public AdminDetail update(@PathVariable long id,@Valid @RequestBody UpdateRequest r){return service.update(id,r);}@PutMapping("/{id}/days")public AdminDetail days(@PathVariable long id,@Valid @RequestBody List<@Valid DayBody> r){return service.setDays(id,r);}@PutMapping("/{id}/translations/{lang}")public AdminDetail text(@PathVariable long id,@PathVariable String lang,@Valid @RequestBody TranslationBody r){return service.text(id,lang,r);}@DeleteMapping("/{id}/translations/{lang}")public ResponseEntity<Void> deleteText(@PathVariable long id,@PathVariable String lang){service.deleteText(id,lang);return ResponseEntity.noContent().build();}@PutMapping("/{id}/images")public AdminDetail images(@PathVariable long id,@Valid @RequestBody ImagesRequest r){return service.images(id,r);}@PostMapping("/{id}/publish")public AdminDetail publish(@PathVariable long id){return service.status(id,ContentStatus.PUBLISHED);}@PostMapping("/{id}/unpublish")public AdminDetail unpublish(@PathVariable long id){return service.status(id,ContentStatus.DRAFT);}@PostMapping("/{id}/archive")public AdminDetail archive(@PathVariable long id){return service.status(id,ContentStatus.ARCHIVED);}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@PathVariable long id){service.delete(id);return ResponseEntity.noContent().build();}}
